import sys

data = list(map(int, sys.stdin.buffer.read().split()))
n = data[0]
a = data[1:]

INF = 10**18
ans = [INF] * n

best = INF
for i in range(n):
    if a[i] != -1:
        best = min(best, a[i] - i)
    if best != INF:
        ans[i] = best + i

best = INF
for i in range(n - 1, -1, -1):
    if a[i] != -1:
        best = min(best, a[i] + i)
    if best != INF:
        ans[i] = min(ans[i], best - i)

print(*ans)
